import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import images from "../images";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <Palette />
      <section className={styles.container}>
      <article className={styles.section}>
          <div className="max-w-6xl mx-auto p-8">
            <h1 className={styles.title}>{t("home.slogan")}</h1>
            <p className="text-lg mt-4">{t("home.intro")}</p>
            
            <div className="">
              <div className="grid grid-cols-3 gap-4">
                {Array.from({ length: 9 }).map((_, index) => {
                  const content2 = t(`home.services.${index}.content2`, "");
                  return (
                  <div key={index} className="bg-primary p-4 border-b pb-4 text-center">
                    <img src={images.icon.src} alt={images.icon.src} className="w-10 h-10 mx-auto" />
                    <div className="flex flex-col items-center justify-center self-center h-full px-8 pb-8">
                      <h3 className="text-xl font-bold text-accent">{t(`home.services.${index}.title`)}</h3>
                      <p className="text-accent-800">{t(`home.services.${index}.content`)}</p>
                      {content2 && <p className="text-accent-800">{content2}</p>}
                    </div>
                  </div>
                )
                })}
              </div>
            </div>

            
          </div>
        </article>
      </section>
    </Layout>
  )
}

export default IndexPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col justify-center items-center w-full ",
  section: "bg-primary/30 border-secondary flex my-8 w-full border shadow-md",
  title: "text-4xl text-accent",
}